 const featuredIndexes=FEATURED_DEMOS[tvRouteIndex],extraIndexes=tvDemos.map((_,index)=>index).filter(index=>!featuredIndexes.includes(index));
 const routeCount=TV_ROUTE.length,routeNumber=tvRouteIndex+1;
 const research=researchIndex===null?null:RESEARCH_SCENARIOS[researchIndex];
