 const dustReading=dustState(parameter),iceWeight=.25+.4*parameter,iceReadings=iceCriteria(iceWeight),iceBest=Math.max(...iceReadings.map(site=>site.score)),oxygenReading=oxygenState(parameter),shieldReading=shieldState(parameter),energyReading=roverEnergyState(parameter);
 const motionAvailable=step.name!=='Reserva y estabilidad'&&(['route','vectors','tangentVector','curvature','routeMarkers','safeSpeed','solarPower'].includes(step.target)||isAnimatedDemo(step));
 const callouts=research||error||(tvItem.section===8||tvItem.section===9)&&!cinematic?[]:sceneCallouts(step,parameter);
 const progressResult=research?undefined:sceneProgressResult(step,parameter);
 const motionFinished=paused&&parameter>=.999&&step.target!=='roverEnergy';
 const areaAngle=-Math.PI/4+(.15+.7*parameter)*Math.PI/4;
 const areaGradient=grad(66*Math.cos(areaAngle),66*Math.sin(areaAngle));
 const areaFactor=Math.sqrt(1+areaGradient[0]**2+areaGradient[1]**2);
 const regionEvidence=step.name==='Región, límites y orden',volumeEvidence=step.name==='Volumen bajo f';
 const campusView=regionEvidence&&(phaseVCamera==='campus'||phaseVCamera==='auto'&&parameter<.18);
 const cutAngle=-Math.PI/4+parameter*Math.PI/4;
 const cutHeight=height(66*Math.cos(cutAngle),66*Math.sin(cutAngle));
 const partialEvidence=step.name==='Derivadas parciales',partialGradient=grad(40,-20);
 const partialStage=parameter<.4?'1 · corte y = −20 m':parameter<.8?'2 · corte x = 40 m':'3 · reunir las dos tasas en ∇f(P)';
 const linearEvidence=step.target==='linear',linearSample=linearizationAt(parameter),linearStage=parameter<.25?'1 · construir el plano en P':parameter<.75?'2 · avanzar desde P hacia H':'3 · comparar las dos cotas en H';
 const directionalEvidence=step.target==='directionalQ'||step.target==='directional',directionalQ=step.target==='directionalQ',directionalSample=directionalQ?directionalAtQ(parameter):directionalAtP(parameter);
